namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly List<Notification> _notifications;
    private int _nextId;
    private readonly Lock _lock = new();

    public NotificationService()
    {
        _notifications =
        [
            new(1, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-30)),
            new(2, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-15)),
            new(3, "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-5)),
        ];
        _nextId = 4;
    }

    /// <summary>Returns all notifications ordered by most recent first.</summary>
    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    /// <summary>Returns notifications added after the given timestamp.</summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(DateTime since)
    {
        // Simulate a new notification arriving roughly every 10 seconds.
        lock (_lock)
        {
            if (_notifications.Count == 0 || _notifications.Max(n => n.Timestamp) < DateTime.UtcNow.AddSeconds(-8))
            {
                var id = _nextId++;
                _notifications.Add(new Notification(id, $"New event #{id} occurred.", DateTime.UtcNow));
            }

            return Task.FromResult(
                _notifications.Where(n => n.Timestamp > since)
                              .OrderByDescending(n => n.Timestamp)
                              .ToList());
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject NotificationsApp.Services.NotificationService NotificationSvc
@inject PersistentComponentState ApplicationState

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = [];
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistSub;

    protected override async Task OnInitializedAsync()
    {
        _persistSub = ApplicationState.RegisterOnPersisting(PersistNotifications);

        // If state was persisted from the SSR pass, reuse it — don't call the service again.
        if (ApplicationState.TryTakeFromJson<List<Notification>>("notifications", out var restored))
        {
            _notifications = restored!;
        }
        else
        {
            _notifications = await NotificationSvc.GetNotificationsAsync();
        }
    }

    private Task PersistNotifications()
    {
        ApplicationState.PersistAsJson("notifications", _notifications);
        return Task.CompletedTask;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender only fires on the interactive runtime — never during static SSR.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                var since = _notifications.Count > 0
                    ? _notifications.Max(n => n.Timestamp)
                    : DateTime.MinValue;

                var newer = await NotificationSvc.GetNotificationsSinceAsync(since);

                if (newer.Count > 0)
                {
                    // Prepend new items (already sorted newest-first).
                    _notifications.InsertRange(0, newer);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _persistSub.Dispose();
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

